import { decode, convertbits } from './bech32/decode.mjs';

const prog = process.argv[1].split('/').pop();

const USAGE = `usage: ${prog} [-h] --a A --b B`;

function printHelp() {
  console.log(USAGE);
  console.log('');
  console.log('options:');
  console.log('  -h, --help  show this help message and exit');
  console.log('  --a A');
  console.log('  --b B');
}

function error(msg) {
  console.error(USAGE);
  console.error(`${prog}: error: ${msg}`);
  process.exit(2);
}

function parseArgs(argv) {
  const args = { a: undefined, b: undefined };
  const extras = [];

  for (let i = 0; i < argv.length; i++) {
    const token = argv[i];

    if (token === '-h' || token === '--help') {
      printHelp();
      process.exit(0);
    }

    let name = null;
    let value = undefined;

    if (token === '--a' || token === '--b') {
      name = token.slice(2);
    } else if (token.startsWith('--a=')) {
      name = 'a';
      value = token.slice(4);
    } else if (token.startsWith('--b=')) {
      name = 'b';
      value = token.slice(4);
    } else {
      extras.push(token);
      continue;
    }

    if (value === undefined) {
      if (i + 1 >= argv.length || argv[i + 1].startsWith('-')) {
        error(`argument --${name}: expected one argument`);
      }
      value = argv[++i];
    }

    args[name] = value;
  }

  const missing = [];
  if (args.a === undefined) missing.push('--a');
  if (args.b === undefined) missing.push('--b');
  if (missing.length > 0) {
    error(`the following arguments are required: ${missing.join(', ')}`);
  }

  if (extras.length > 0) {
    error(`unrecognized arguments: ${extras.join(' ')}`);
  }

  return args;
}

function main() {
  const args = parseArgs(process.argv.slice(2));

  const decoded = decode(args.a, args.b);
  if (decoded[0] !== null && decoded[1] !== null) {
    const witver = decoded[0];
    const witprog = decoded[1];
    const converted = convertbits(witprog, 5, 8);
    console.log(witver);
    console.log(converted === null ? 'None' : `[${converted.join(', ')}]`);
  }
}

main();

