import { hrpExpand, polymod, CHARSET } from '/output/bech32/encoding.mjs';
import { convertbits } from '/output/bech32/convertbits.mjs';
function createChecksum(hrp, data, spec) {
  const c = spec === 'bech32m' ? 0x2bc830a3 : 1;
  const values = hrpExpand(hrp).concat(data).concat([0,0,0,0,0,0]);
  const pm = polymod(values) ^ c;
  const ret = [];
  for (let p = 0; p < 6; p++) ret.push((pm >> (5 * (5 - p))) & 31);
  return ret;
}
function encode(hrp, witver, progBytes) {
  const spec = witver === 0 ? 'bech32' : 'bech32m';
  const data = [witver].concat(convertbits(progBytes, 8, 5, true));
  const combined = data.concat(createChecksum(hrp, data, spec));
  return hrp + '1' + combined.map(d => CHARSET[d]).join('');
